Pattern.Good:

// src/test/kotlin/com/example/user/UserFormatterTest.kt
package com.example.user

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class UserFormatterTest {
    @Test
    fun `formats a user with first and last name`() {
        val user = User(first = "Ada", last = "Lovelace")
        assertEquals("Ada Lovelace", UserFormatter.format(user))
    }
}

Pattern.Bad:

class UserFormatterTest {
    @Test
    fun formats() {
        val context = mockk<android.content.Context>()
        every { context.getString(any()) } returns "Ada Lovelace"
        // …
    }
}

Pattern.Good:

// src/test/kotlin/com/example/prefs/UserPrefsRobolectricTest.kt
package com.example.prefs

import android.content.Context
import androidx.test.core.app.ApplicationProvider
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import kotlin.test.assertEquals

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class UserPrefsRobolectricTest {
    @Test
    fun `writes and reads back a nickname`() {
        val ctx: Context = ApplicationProvider.getApplicationContext()
        val prefs = UserPrefs(ctx)
        prefs.setNickname("ada")
        assertEquals("ada", prefs.getNickname())
    }
}


// src/androidTest/kotlin/com/example/db/UserDaoInstrumentedTest.kt
package com.example.db

import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import androidx.room.Room
import org.junit.After
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import kotlin.test.assertEquals

@RunWith(AndroidJUnit4::class)
class UserDaoInstrumentedTest {
    private lateinit var db: UserDatabase

    @Before fun setUp() {
        val ctx = InstrumentationRegistry.getInstrumentation().targetContext
        db = Room.inMemoryDatabaseBuilder(ctx, UserDatabase::class.java).build()
    }

    @After fun tearDown() { db.close() }

    @Test fun `inserts and reads back a user`() {
        val dao = db.userDao()
        dao.insert(UserEntity(id = 1, name = "Ada"))
        assertEquals("Ada", dao.byId(1)?.name)
    }
}
